// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;500;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SystemStackProps = Record<string, any>;

const SystemStack: React.FC<SystemStackProps> = ({
  backgroundColor = "#0d1117",
  transparentBackground = false,
  durationInSeconds = 10,
  accentColor = "#FFD700",
  layerColor = "#161b22",
  textColor = "#e6edf3",
  layers = ["Requests", "Backlog", "Sprint", "Delivery"],
  loadIntensityMax = 98,
}) => {
  {/* Load Google Fonts */}
  useFontLoader(["Inter"]);
  {/* End Load Google Fonts */}

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Sizing & Layout calculations
  const total = layers.length;
  const blockHeight = height * 0.12;
  const blockWidth = width * 0.45;
  const gap = height * 0.03;
  const totalHeight = total * blockHeight + (total - 1) * gap;
  const startY = (height - totalHeight) / 2 + height * 0.05; // Slightly lower center
  const startX = (width - blockWidth) / 2;

  // Timing
  const buildDuration = fps * 2;
  const holdDuration = fps * 1;
  const wobbleStartFrame = buildDuration + holdDuration;
  const wobbleRampDuration = fps * 4;

  // Load Indicator Logic
  const loadPercent = interpolate(
    frame,
    [wobbleStartFrame - fps, wobbleStartFrame + wobbleRampDuration],
    [15, loadIntensityMax],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const isHighLoad = loadPercent > 85;
  const indicatorColor = isHighLoad ? accentColor : textColor;
  const alertOpacity = isHighLoad ? Math.abs(Math.sin(frame * 0.15)) * 0.8 + 0.2 : 0;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", overflow: "hidden" }}>
      
      {/* Background Grid Pattern for Corporate Tech Feel */}
      <div 
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          backgroundImage: `
            linear-gradient(to right, ${textColor}08 1px, transparent 1px),
            linear-gradient(to bottom, ${textColor}08 1px, transparent 1px)
          `,
          backgroundSize: `${width * 0.05}px ${height * 0.089}px`,
          opacity: 0.5,
          transition: "none",
        }}
      />

      {/* System Load Indicator (Top Right) */}
      <div style={{
        position: "absolute",
        top: height * 0.08,
        right: width * 0.08,
        display: "flex",
        flexDirection: "column",
        alignItems: "flex-end",
        transition: "none",
      }}>
        <div style={{
          fontSize: height * 0.025,
          color: textColor,
          opacity: 0.6,
          letterSpacing: "0.1em",
          fontWeight: 600,
          textTransform: "uppercase",
          transition: "none",
        }}>
          System Load
        </div>
        <div style={{
          fontSize: height * 0.08,
          color: indicatorColor,
          fontWeight: 700,
          fontVariantNumeric: "tabular-nums",
          lineHeight: 1,
          marginTop: height * 0.01,
          textShadow: isHighLoad ? `0 0 20px ${accentColor}66` : "none",
          transition: "none",
        }}>
          {Math.round(loadPercent)}%
        </div>
        
        {/* Warning Badge */}
        <div style={{
          marginTop: height * 0.02,
          padding: `${height * 0.01}px ${width * 0.015}px`,
          backgroundColor: `${accentColor}22`,
          border: `1px solid ${accentColor}`,
          color: accentColor,
          fontSize: height * 0.02,
          fontWeight: 600,
          borderRadius: 4,
          opacity: alertOpacity,
          letterSpacing: "0.05em",
          transition: "none",
        }}>
          CAPACITY WARNING
        </div>
      </div>

      {/* Stack Layers */}
      {layers.map((label, index) => {
        // Reverse index: 0 is bottom (Delivery), total-1 is top (Requests)
        const indexFromBottom = total - 1 - index;
        const levelFactor = indexFromBottom / (total - 1 || 1); 

        // Initial Build Animation
        const dropDelay = indexFromBottom * 8; 
        const buildSpring = spring({
          frame: frame - dropDelay,
          fps,
          config: { damping: 14, stiffness: 90, mass: 1.2 },
        });

        const initialYOffset = interpolate(buildSpring, [0, 1], [-height * 1.5, 0]);
        const initialScale = interpolate(buildSpring, [0, 1], [0.8, 1]);
        const initialOpacity = interpolate(buildSpring, [0, 0.5, 1], [0, 0, 1]);

        // Wobble Animation
        const localWobbleStart = wobbleStartFrame + (indexFromBottom * 5);
        const wobbleIntensity = interpolate(
          frame,
          [localWobbleStart, localWobbleStart + wobbleRampDuration],
          [0, 1],
          { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
        );

        // Complex organic wobble using multiple sine waves
        // The top layers (high levelFactor) wobble significantly more than bottom layers
        const wobblePhase1 = frame * 0.08 + indexFromBottom * 0.5;
        const wobblePhase2 = frame * 0.13 - indexFromBottom * 0.3;
        
        // Rotational Wobble
        const maxAngle = 7; 
        const angle = (Math.sin(wobblePhase1) * 0.6 + Math.cos(wobblePhase2) * 0.4) 
                      * maxAngle 
                      * wobbleIntensity 
                      * Math.pow(levelFactor, 1.2);
        
        // Translation Wobble (Horizontal shifting)
        const maxOffsetX = width * 0.035;
        const xOffset = (Math.cos(wobblePhase1 * 1.2) * 0.5 + Math.sin(wobblePhase2 * 1.5) * 0.5) 
                        * maxOffsetX 
                        * wobbleIntensity 
                        * Math.pow(levelFactor, 1.5);
                        
        // Translation Wobble (Vertical bouncing under strain)
        const maxOffsetY = height * 0.015;
        const yOffsetStrain = (Math.sin(frame * 0.2 + indexFromBottom) * 0.5 + 0.5) 
                              * maxOffsetY 
                              * wobbleIntensity 
                              * levelFactor;

        // Final Positioning
        const yPos = startY + index * (blockHeight + gap);

        return (
          <div
            key={index}
            style={{
              position: "absolute",
              top: yPos,
              left: startX,
              width: blockWidth,
              height: blockHeight,
              backgroundColor: layerColor,
              borderRadius: 8,
              border: `1px solid ${textColor}22`,
              borderLeft: `6px solid ${levelFactor > 0.6 && isHighLoad ? accentColor : textColor}88`,
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              padding: `0 ${width * 0.03}px`,
              boxShadow: `0px ${height * 0.02}px ${height * 0.04}px rgba(0,0,0,0.4)`,
              opacity: initialOpacity,
              transformOrigin: "center bottom",
              transform: `
                translateY(${initialYOffset + yOffsetStrain}px) 
                translateX(${xOffset}px) 
                scale(${initialScale}) 
                rotateZ(${angle}deg)
              `,
              transition: "none",
            }}
          >
            {/* Layer Label */}
            <div style={{ 
              display: "flex", 
              alignItems: "center",
              gap: width * 0.015,
              transition: "none",
            }}>
              {/* Abstract Icon/Marker */}
              <div style={{
                width: height * 0.015,
                height: height * 0.015,
                backgroundColor: textColor,
                borderRadius: "50%",
                opacity: 0.3,
                transition: "none",
              }}/>
              <span style={{ 
                color: textColor, 
                fontSize: height * 0.035, 
                fontWeight: 600,
                letterSpacing: "-0.02em",
                transition: "none",
              }}>
                {label}
              </span>
            </div>
            
            {/* Layer Index/Meta */}
            <div style={{
              color: textColor,
              opacity: 0.3,
              fontSize: height * 0.02,
              fontFamily: "monospace",
              transition: "none",
            }}>
              L{indexFromBottom.toString().padStart(2, "0")}
            </div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

export default SystemStack;